def group_tuples(Input):
    """Write a function to find common first element in given list of tuple."""
    grouped = {}
    for tup in Input:
        key = tup[0]
        rest = tup[1:]
        if key in grouped:
            grouped[key].extend(rest)
        else:
            grouped[key] = list(rest)
    return [tuple([key] + values) for key, values in grouped.items()]
